from pathlib import Path
from html import escape as e
P=Path(__file__).parent/'dist'
content={
'zh':dict(lang='zh-CN',name='易开 PHP 面板',title='把环境交给易开，<br>专心做好网站。',desc='简单好用的 Windows 本地 PHP 开发环境。项目、域名、数据库，在一个面板里管理。',nav=['功能','迁移','快速开始','获取软件'],eyebrow='YIKAI PHP · 为本地开发而做',side='从第一个本地网站，到手上的多个项目。启动环境、打开后台、管理数据库，让日常操作少绕一点路。',cta='获取易开 PHP',second='了解使用方式',fine='Windows x64 · 中文 / English / 日本語',shot='真实面板界面 · 0.6.5',shotnote='界面实拍：演示项目处于停止状态。',strip=['多项目管理','独立启停','本地域名','文件与数据库保存在本机'],ftitle='常用的操作，<br>都在顺手的位置。',fdesc='围绕本地建站的日常流程设计，让配置环境这件事更简单。',features=[('项目，一目了然','搜索项目、收藏星标、查看目录大小。常用项目放在前面，切换时更容易找到。'),('运行环境，清楚可见','Nginx、PHP 与 MySQL 的运行状态和端口集中显示。支持环境统一启停和项目独立启停。'),('域名与伪静态','使用自己的 .yikai 本地域名，同步 hosts。按项目配置伪静态规则，处理网站路由。'),('数据库，直接管理','支持 MySQL 8.0、5.7 和 SQLite。简洁管理页面配合 Adminer，支持 root 密码修改与重置。'),('后台入口，少找一步','分析并记住项目后台地址，也可以手动指定。打开网站、后台和目录，入口集中在项目中。'),('熟悉的三种语言','面板与简洁数据库页面支持中文、英文、日文。选择顺手的语言，再开始工作。')],mtitle='把现有网站，<br>一起带过来。',mdesc='从 PHPStudy 扫描项目，批量全选或逐个勾选。网站文件和对应数据库复制到易开，原环境保留。',mnote='支持源码配置扫描辅助识别数据库。YikaiCMS / WordPress 可自动改写连接配置；其他项目需检查配置。',source='原 PHPStudy',original='原网站与数据库保留',copy='复制所选网站 + 完整数据库',dest='易开 PHP 面板',destnote='导入后按需启动项目',stitle='开始使用，只需几步。',sdesc='默认工作目录 D:\\yikai。网站和运行软件分开放，查找与管理更方便。',steps=[('准备本地环境','将完整环境放到 D:\\yikai，打开易开 PHP 面板。'),('添加你的项目','新建项目、接入现有目录，或从 PHPStudy 复制导入。'),('启动，开始工作','同步本地域名，启动项目，然后打开网站或后台。')],dtitle='选择适合你的易开。',ddesc='官网现已开放。可公开下载的安装包正在整理，完成后会在这里提供。',pack=[('全量环境包','面向首次使用，规划提供面板、PHP、Nginx、数据库与配套工具。'),('最小环境包','面向轻量安装，规划只保留基础组件，按需补充其他环境。')],planned='规划中',waiting='安装包尚未开放下载',contact='咨询与反馈',qtitle='你可能还想了解',faq=[('已经有 PHPStudy，需要先卸载吗？','不需要。复制导入保留原网站和数据库。导入完成后，请检查项目配置，避免两个环境使用相同端口或域名。'),('可以直接复制 MySQL 数据目录吗？','所选项目迁移采用数据库导出与导入。同版本也不默认复制整个数据目录，以免把其他数据库和实例配置一起带入。'),('支持哪些 PHP 版本？','当前面板支持已安装的 PHP 8.0、8.2、8.5 环境切换，默认使用 PHP 8.2。未来公开安装包的具体组件，以下载说明为准。'),('在线更新已经开放了吗？','面板已提供检查更新入口。更新服务和公开安装包仍在准备中；当前不会提供无法下载的升级文件。')],foot='简单好用的本地 PHP 开发环境',skip='跳转到正文'),
'en':dict(lang='en',name='Yikai PHP',title='Less setup.<br>More building.',desc='A straightforward local PHP environment for Windows. Manage projects, domains and databases in one place.',nav=['Features','Migration','Get started','Get Yikai'],eyebrow='YIKAI PHP · BUILT FOR LOCAL DEVELOPMENT',side='From your first local website to a growing collection of projects. Start your environment, open the admin page and manage your database with fewer steps.',cta='Get Yikai PHP',second='How it works',fine='Windows x64 · 中文 / English / 日本語',shot='Actual application · 0.6.5',shotnote='Application capture: the example project is stopped.',strip=['Multiple projects','Per-project controls','Local domains','Files and databases stay on your PC'],ftitle='Everyday tools.<br>Right where you need them.',fdesc='Designed around the everyday work of running websites locally.',features=[('Projects at a glance','Search, star your favorites and calculate folder sizes. Keep frequently used projects easy to find.'),('Know what is running','See the status and ports of Nginx, PHP and MySQL. Control the whole environment or individual projects.'),('Domains and URL rewrites','Use custom .yikai domains, synchronize hosts and configure rewrite rules for each project.'),('Database tools included','MySQL 8.0, 5.7 and SQLite support. A simple database page with Adminer, plus MySQL root password changes and resets.'),('Find the admin page','Detect and remember admin URLs, or set one manually. Open the website, admin page and folder from one place.'),('Three familiar languages','Use the panel and simple database pages in Chinese, English or Japanese.')],mtitle='Bring your<br>existing websites along.',mdesc='Scan PHPStudy projects and select one or all. Copy website files and their complete databases into Yikai while keeping the original environment.',mnote='Source configuration scanning helps identify databases. YikaiCMS and WordPress connections can be rewritten automatically; review other project configurations manually.',source='Original PHPStudy',original='Original websites and databases retained',copy='Copy selected websites + complete databases',dest='Yikai PHP',destnote='Start imported projects when ready',stitle='A few steps to get started.',sdesc='The default workspace is D:\\yikai, with separate folders for websites and runtime software.',steps=[('Prepare your environment','Place the full environment in D:\\yikai and open Yikai PHP.'),('Add a project','Create a project, connect an existing folder or copy projects from PHPStudy.'),('Start building','Sync local domains, start the project and open its website or admin page.')],dtitle='Choose your Yikai.',ddesc='The website is live. Public installation packages are being prepared and will be available here when ready.',pack=[('Full environment','Planned for first-time setup: the panel, PHP, Nginx, databases and supporting tools.'),('Minimal environment','Planned for a smaller setup with basic components and optional environments later.')],planned='Planned',waiting='Download not yet available',contact='Contact & feedback',qtitle='Good to know',faq=[('Do I need to uninstall PHPStudy?','No. Copy import preserves the original files and databases. Check project configuration afterward to avoid domain and port conflicts.'),('Does migration copy the MySQL data directory?','Selected-project migration uses database export and import. It does not copy the entire instance directory, even for matching versions.'),('Which PHP versions are supported?','The panel can switch between installed PHP 8.0, 8.2 and 8.5 environments, with PHP 8.2 as the default. Public package contents will be documented on release.'),('Are online updates available?','The panel has an update check. The update service and public installation packages are still being prepared.')],foot='A simpler local PHP environment',skip='Skip to content'),
'ja':dict(lang='ja',name='Yikai PHP',title='環境づくりは易開に。<br>サイト制作に集中。',desc='Windows 向けの使いやすいローカル PHP 環境。プロジェクト、ドメイン、データベースをひとつのパネルで管理。',nav=['機能','移行','使い方','ダウンロード'],eyebrow='YIKAI PHP · ローカル開発のために',side='初めてのサイトから複数のプロジェクトまで。環境の起動、管理画面へのアクセス、データベース操作をもっと手軽に。',cta='Yikai PHP を入手',second='使い方を見る',fine='Windows x64 · 中文 / English / 日本語',shot='実際の画面 · 0.6.5',shotnote='画面例：サンプルプロジェクトは停止中です。',strip=['複数サイトの管理','個別に起動・停止','ローカルドメイン','ファイルと DB はこの PC に保存'],ftitle='よく使う操作を、<br>使いやすい場所に。',fdesc='ローカルでのサイト制作に必要な操作をまとめました。',features=[('プロジェクトを見つけやすく','検索、スター、フォルダー容量の計算。よく使うプロジェクトにすばやくアクセス。'),('稼働状況を確認','Nginx、PHP、MySQL の状態とポートを表示。環境全体とプロジェクト個別の起動・停止に対応。'),('ドメインとリライト','独自の .yikai ドメインを設定し、hosts を同期。プロジェクトごとにリライトルールを設定できます。'),('データベース管理','MySQL 8.0、5.7、SQLite に対応。シンプルな管理画面と Adminer、root パスワードの変更・リセットも。'),('管理画面をすぐに開く','管理画面の URL を検出して記憶。手動設定も可能。サイトやフォルダーにも直接アクセスできます。'),('3 つの言語に対応','パネルと簡易 DB 管理画面は日本語、中国語、英語で使用できます。')],mtitle='既存のサイトも、<br>一緒に移行。',mdesc='PHPStudy をスキャンし、個別または一括で選択。サイトファイルと対応する DB をコピーし、元の環境は保持します。',mnote='ソース設定のスキャンで DB 検出を補助。YikaiCMS / WordPress の接続設定は自動変更に対応。その他の設定は手動で確認してください。',source='元の PHPStudy',original='元のサイトと DB は保持',copy='選択したサイトと DB をコピー',dest='Yikai PHP',destnote='取り込み後、必要に応じて起動',stitle='数ステップでスタート。',sdesc='標準ディレクトリは D:\\yikai。サイトと実行ソフトウェアを分けて管理します。',steps=[('環境を準備','フル環境を D:\\yikai に配置して Yikai PHP を開きます。'),('プロジェクトを追加','新規作成、既存フォルダーの接続、PHPStudy からのコピーを選択。'),('制作を開始','ドメインを同期して起動し、サイトまたは管理画面を開きます。')],dtitle='用途に合った易開を。',ddesc='公式サイトを公開しました。インストールパッケージは準備ができ次第、こちらで提供します。',pack=[('フル環境パッケージ','初回導入向け。パネル、PHP、Nginx、DB、関連ツールの同梱を予定。'),('最小環境パッケージ','基本コンポーネントを中心とする軽量版。追加環境は必要に応じて導入する予定。')],planned='計画中',waiting='ダウンロードは準備中です',contact='お問い合わせ',qtitle='よくある質問',faq=[('PHPStudy の削除は必要ですか？','不要です。コピーでは元のサイトと DB を保持します。移行後に設定を確認し、ポートやドメインの重複を避けてください。'),('MySQL のデータフォルダーを直接コピーしますか？','選択したプロジェクトの移行には DB のエクスポートとインポートを使用します。同じバージョンでもインスタンス全体はコピーしません。'),('対応する PHP バージョンは？','インストール済みの PHP 8.0、8.2、8.5 を切り替えられます。標準は PHP 8.2。公開パッケージの詳細は提供時にご案内します。'),('オンライン更新は利用できますか？','パネルには更新確認機能があります。更新サービスと公開パッケージは現在準備中です。')],foot='使いやすいローカル PHP 開発環境',skip='本文へ移動')}
for code,d in content.items():
 root='' if code=='zh' else code+'/'
 langs=''.join(f'<a href="/{"" if c=="zh" else c+"/"}" lang="{content[c]["lang"]}" '+('aria-current="page" ' if c==code else '')+f'>{label}</a>' for c,label in [('zh','中文'),('en','EN'),('ja','日本語')])
 features=''.join(f'<article class="feature"><span class="number">0{i+1}</span><h3>{e(t)}</h3><p>{e(p)}</p></article>' for i,(t,p) in enumerate(d['features']))
 steps=''.join(f'<article class="step"><h3>{e(t)}</h3><p>{e(p)}</p></article>' for t,p in d['steps'])
 packages=''.join(f'<article class="package"><span class="tag">{d["planned"]}</span><h3>{e(t)}</h3><p>{e(p)}</p><span class="unavailable">{d["waiting"]}</span></article>' for t,p in d['pack'])
 faq=''.join(f'<details><summary>{e(t)}</summary><p>{e(p)}</p></details>' for t,p in d['faq'])
 nav=''.join(f'<a href="#{id}">{text}</a>' for id,text in zip(['features','migration','start','download'],d['nav']))
 html=f'''<!doctype html><html lang="{d['lang']}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{d['name']} · {d['foot']}</title><meta name="description" content="{e(d['desc'],quote=True)}"><link rel="canonical" href="https://panel.yikai.cn/{root}"><link rel="alternate" hreflang="zh-CN" href="https://panel.yikai.cn/"><link rel="alternate" hreflang="en" href="https://panel.yikai.cn/en/"><link rel="alternate" hreflang="ja" href="https://panel.yikai.cn/ja/"><link rel="alternate" hreflang="x-default" href="https://panel.yikai.cn/"><link rel="icon" href="/assets/favicon.ico"><link rel="icon" type="image/svg+xml" href="/assets/logo.svg"><meta name="theme-color" content="#245c4a"><link rel="stylesheet" href="/assets/site.css"></head><body><a class="skip" href="#main">{d['skip']}</a><header><div class="wrap nav"><a class="brand" href="/{root}"><img src="/assets/logo.svg" alt="" width="36" height="36"><span>{d['name']}<small>YIKAI PHP</small></span></a><nav aria-label="Navigation">{nav}</nav><div class="languages">{langs}</div></div></header><main id="main"><div class="wrap"><section class="hero"><div><div class="eyebrow"><span class="dot"></span>{d['eyebrow']}</div><h1>{d['title']}</h1><p>{d['desc']}</p><div class="actions"><a class="button primary" href="#download">{d['cta']} <span aria-hidden="true">↓</span></a><a class="button" href="#start">{d['second']} <span aria-hidden="true">↗</span></a></div><p class="fine">{d['fine']}</p></div><div class="hero-side"><p>{d['side']}</p><div class="pills"><span class="pill">PHP</span><span class="pill">Nginx</span><span class="pill">MySQL</span><span class="pill">SQLite</span></div></div></section><div class="product-stage"><div class="stage-label"><span>{d['shot']}</span><span>LOCAL ENVIRONMENT, SIMPLIFIED.</span></div><a href="/assets/panel-{code}.webp" aria-label="{d['shot']}"><img src="/assets/panel-{code}.webp" width="1320" height="820" alt="{d['shot']}" fetchpriority="high"></a></div><div class="caption">{d['shotnote']}</div><div class="strip">{''.join('<span>'+e(t)+'</span>' for t in d['strip'])}</div><section id="features" class="section"><div class="section-top"><h2>{d['ftitle']}</h2><p>{d['fdesc']}</p></div><div class="features">{features}</div></section><section id="migration" class="section migration"><div><div class="eyebrow">PHPSTUDY → YIKAI PHP</div><h2>{d['mtitle']}</h2><p>{d['mdesc']}</p><p class="fine">{d['mnote']}</p></div><div class="flow"><div class="flow-row"><div><div class="flow-title">{d['source']}</div><small>{d['original']}</small></div><span aria-hidden="true">▤</span></div><div class="flow-line">↓ {d['copy']}</div><div class="flow-dest"><div class="flow-row"><span class="flow-title">{d['dest']}</span><img src="/assets/logo.svg" alt="" width="32" height="32"></div><small>{d['destnote']}</small></div></div></section><section id="start" class="section"><div class="section-top"><h2>{d['stitle']}</h2><p>{e(d['sdesc'])}</p></div><div class="steps">{steps}</div></section><section id="download" class="section"><div class="download"><div class="eyebrow">WINDOWS x64</div><h2>{d['dtitle']}</h2><p>{d['ddesc']}</p><div class="packages">{packages}</div><a class="button" href="mailto:support@yikay.com">{d['contact']} <span aria-hidden="true">↗</span></a></div></section><section class="section faq"><h2>{d['qtitle']}</h2>{faq}</section></div></main><footer class="wrap footer"><div><a class="brand" href="/{root}"><img src="/assets/logo.svg" alt="" width="30" height="30"><span>{d['name']}</span></a><p>{d['foot']} · © 2026 Yikai PHP</p></div><div class="footer-links"><a href="mailto:support@yikay.com">support@yikay.com</a><a href="https://www.yikaicms.com">YikaiCMS ↗</a><a href="/assets/logo.svg" download="yikai-php-logo.svg">Logo ↓</a></div></footer></body></html>'''
 (P/root).mkdir(parents=True,exist_ok=True);(P/root/'index.html').write_text(html,encoding='utf8')
(P/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://panel.yikai.cn/sitemap.xml\n',encoding='utf8')
(P/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://panel.yikai.cn/'+r+'</loc></url>' for r in ['', 'en/', 'ja/'])+'</urlset>',encoding='utf8')
print('Built Chinese, English and Japanese static website')
